package steps

import (
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

//truebdd:concept when "doubling"
func concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b(state *State, args []string) error {
	const (
		hostRoot    = "../.."
		servicePath = "./services/calc"
		command     = "double"
	)

	value := args[0]

	run := exec.Command("go", "run", servicePath, command, value)
	run.Dir = hostRoot
	var stderr strings.Builder
	run.Stderr = &stderr

	stdout, err := run.Output()
	if err != nil {
		return fmt.Errorf("go run %s %s %s in %s: %w: %s",
			servicePath, command, value, hostRoot, err, strings.TrimSpace(stderr.String()))
	}

	printed := strings.TrimSpace(string(stdout))
	doubled, err := strconv.Atoi(printed)
	if err != nil {
		return fmt.Errorf("%s %s printed %q, want an integer on stdout: %w",
			command, value, printed, err)
	}

	state.Value = doubled
	return nil
}

package steps

import (
	"fmt"
	"strconv"
)

func Register(suite Registrar) {
	suite.Step(`^the result is (-?\d+)$`, result)

	suite.Step("^the Owner doubles (-?\\d+)$", concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b)
}

//truebdd:concept then "result"
func result(state *State, args []string) error {
	want, err := strconv.Atoi(args[0])
	if err != nil {
		return err
	}
	if state.Value != want {
		return fmt.Errorf("expected %d, got %d", want, state.Value)
	}
	return nil
}

package steps

type State struct {
	Value int
}
type Registrar interface {
	Step(string, func(*State, []string) error)
}
